#!/usr/bin/env python3
"""Generate severity totals for the dated log files in /app/logs."""
from collections import defaultdict
from datetime import date, timedelta
from pathlib import Path
import csv
import re

LOG_DIR = Path('/app/logs')
OUTPUT = Path('/app/summary.csv')
REFERENCE_DATE = date(2025, 8, 12)
SEVERITIES = ('ERROR', 'WARNING', 'INFO')
PERIODS = ('today', 'last_7_days', 'last_30_days', 'month_to_date', 'total')
FILENAME_DATE = re.compile(r'^(\d{4}-\d{2}-\d{2})_[^/]+\.log$')
SEVERITY = re.compile(r'\[(ERROR|WARNING|INFO)\]')


def main():
    counts = {period: defaultdict(int) for period in PERIODS}
    for path in sorted(LOG_DIR.glob('*.log')):
        match = FILENAME_DATE.match(path.name)
        if not match:
            continue
        log_date = date.fromisoformat(match.group(1))
        if log_date == REFERENCE_DATE:
            periods = ('today', 'last_7_days', 'last_30_days', 'month_to_date')
        elif REFERENCE_DATE - timedelta(days=6) <= log_date < REFERENCE_DATE:
            periods = ('last_7_days',)
        elif REFERENCE_DATE - timedelta(days=29) <= log_date < REFERENCE_DATE:
            periods = ('last_30_days',)
        elif log_date.year == REFERENCE_DATE.year and log_date.month == REFERENCE_DATE.month and log_date < REFERENCE_DATE:
            periods = ('month_to_date',)
        else:
            periods = ()

        for line in path.read_text(encoding='utf-8').splitlines():
            severity_match = SEVERITY.search(line)
            if not severity_match:
                continue
            severity = severity_match.group(1)
            counts['total'][severity] += 1
            for period in periods:
                counts[period][severity] += 1

    with OUTPUT.open('w', newline='', encoding='utf-8') as output:
        writer = csv.writer(output, lineterminator='\n')
        writer.writerow(('period', 'severity', 'count'))
        for period in PERIODS:
            for severity in SEVERITIES:
                writer.writerow((period, severity, counts[period][severity]))


if __name__ == '__main__':
    main()
PY
